-- =============================================================================
-- 522 — LE CAHIER D'EXERCICES DE 1RE (partie 10)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/1re/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 522 --niveau 1re --fichiers espagnol.jumelles --suffixe 10 > supabase/contenu/522_exercices_1re_10.sql
--
-- 84 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   espagnol.jumelles       84 exercices · 28 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('e50c16f0-fd80-5177-b3aa-c857f7ad50a8'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Un message avant le cinéma","competence":"comprendre-langue","situation":"Lucía et Marcos organisent une sortie au cinéma. Ils s’écrivent des messages en espagnol.","documents":[{"id":"chat","type":"dialogue","modele":"sms","titre":"Messages de Lucía et Marcos","participants":[{"nom":"Lucía","emoji":"👧","cote":"gauche"},{"nom":"Marcos","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Lucía","texte":"¡Hola, Marcos! ¿Cómo estás?"},{"qui":"Marcos","texte":"Muy bien. ¿Dónde estás tú?"},{"qui":"Lucía","texte":"En casa. ¿Vienes al cine esta tarde?"},{"qui":"Marcos","texte":"¡Sí! ¿Cuándo empieza la película?"},{"qui":"Lucía","texte":"A las seis."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les **trois mots interrogatifs** des questions de Lucía et de Marcos.","aide":"Ils portent tous un accent écrit.","type":"zone","document":"chat","multiple":true},{"enonce":"Lucía répond « A las seis ». Complète la question de Marcos.","aide":"On répond par une heure : quelle est la question ?","type":"trous","segments":["¿",0," empieza la película?"],"banque":["Cuántos","Quién","Dónde","Cuándo"]},{"enonce":"Remets en ordre : « Où est le cinéma ? » La phrase commence par ¿Dónde.","aide":"Le verbe suit le mot interrogatif.","type":"ordre","items":[{"id":"a","texte":"el"},{"id":"b","texte":"¿Dónde"},{"id":"c","texte":"está"},{"id":"d","texte":"cine?"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m2","m6","m17"]},"explication":"**Cómo, dónde, cuándo** : les mots interrogatifs portent toujours un accent écrit, même dans un message rapide."},{"cle":{"type":"trous","trous":[["cuando"]]},"affichage":"Cuándo","explication":"**¿Cuándo empieza la película?** : *cuándo* demande le moment, et « a las seis » est bien une heure."},{"cle":{"type":"ordre","ids":["b","c","a","d"]},"explication":"**¿Dónde está el cine?** : on ouvre par ¿, on met le mot interrogatif avec son accent, puis le verbe, et on ferme par ?."}]$ex$::jsonb),
  ('e50c16f0-fd80-5177-b3aa-c857f7ad50a8'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Au rayon des livres","competence":"manier-langue","situation":"Sara cherche un cadeau pour son frère dans une librairie de Valence. La libraire lui pose plusieurs questions.","documents":[{"id":"tienda","type":"dialogue","modele":"sms","titre":"Dans la librairie","participants":[{"nom":"Libraria","emoji":"👩","cote":"gauche"},{"nom":"Sara","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Libraria","texte":"¿Qué quieres, Sara?"},{"qui":"Sara","texte":"Busco un libro para mi hermano."},{"qui":"Libraria","texte":"¿Qué libro buscas? Tenemos novelas y cómics."},{"qui":"Sara","texte":"Una novela, por favor."},{"qui":"Libraria","texte":"¿Cuál prefieres: la roja o la azul?"},{"qui":"Sara","texte":"La azul. ¡Gracias!"}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le mot interrogatif qui demande de **choisir** entre deux livres.","aide":"Il y a deux livres proposés : on choisit dans un ensemble.","type":"zone","document":"tienda","multiple":false},{"enonce":"Pourquoi la libraire dit-elle « ¿Qué libro buscas? » et non « ¿Cuál libro buscas? » ?","aide":"Regarde ce qui suit le mot interrogatif : un nom.","type":"choix","options":[{"id":"a","texte":"Parce que libro est un mot féminin"},{"id":"b","texte":"Devant un nom, l’espagnol préfère qué"},{"id":"c","texte":"Parce que cuál ne s’emploie qu’au pluriel"},{"id":"d","texte":"Parce que Sara est une cliente régulière"}],"multiple":false},{"enonce":"Complète les deux questions avec **qué** ou **cuál**.","aide":"Premier trou : un nom suit. Second trou : on choisit entre deux livres.","type":"trous","segments":["¿",0," día es hoy? ¿",1," de estos dos libros prefieres?"],"banque":["Cuál","Cuánto","Quién","Qué"]},{"enonce":"Remets en ordre : « Quel film veux-tu voir ? » La phrase commence par ¿Qué.","aide":"Le nom suit directement qué.","type":"ordre","items":[{"id":"a","texte":"¿Qué"},{"id":"b","texte":"quieres"},{"id":"c","texte":"ver?"},{"id":"d","texte":"película"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m20"]},"explication":"**Cuál** demande un choix dans un ensemble (ici la roja ou la azul)."},{"cle":{"type":"choix","ids":["b"]},"explication":"**Qué libro** : devant un nom, on emploie *qué* (¿Qué día es hoy?), pas *cuál*."},{"cle":{"type":"trous","trous":[["que"],["cual"]]},"affichage":"Qué · Cuál","explication":"**¿Qué día es hoy?** (qué devant un nom) et **¿Cuál de estos dos libros prefieres?** (un choix dans un ensemble)."},{"cle":{"type":"ordre","ids":["a","d","b","c"]},"explication":"**¿Qué película quieres ver?** : qué + nom, puis le verbe, sans inversion du sujet."}]$ex$::jsonb),
  ('e50c16f0-fd80-5177-b3aa-c857f7ad50a8'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Pourquoi n’es-tu pas venue ?","competence":"analyser-document","situation":"Ana n’est pas venue à la fête de Pablo. Il lui écrit un courriel, et elle lui répond par message.","documents":[{"id":"correo","type":"texte","genre":"lettre","titre":"Correo de Pablo","blocs":["Hola, Ana:","Ayer no viniste a mi fiesta y no entiendo el porqué. ¿Por qué no me llamaste?","Mi madre pregunta dónde vives ahora y yo no sé qué decirle.","Un abrazo, Pablo"],"source":"Texte écrit pour l’exercice"},{"id":"resp","type":"dialogue","modele":"sms","titre":"Réponse d’Ana","participants":[{"nom":"Ana","emoji":"👧","cote":"gauche"},{"nom":"Pablo","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Ana","texte":"Perdona, Pablo. No fui porque estaba enferma."},{"qui":"Pablo","texte":"¡Ah! Entonces no pasa nada."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le **nom masculin** qui signifie « la raison » dans le courriel.","aide":"Il s’écrit en un seul mot, avec un accent, après el.","type":"zone","document":"correo","multiple":false},{"enonce":"Touche le mot qui **répond** à la question de Pablo (« Pourquoi n’es-tu pas venue ? »).","aide":"Il introduit la cause, sans accent.","type":"zone","document":"resp","multiple":false},{"enonce":"Complète la question de Pablo et la réponse d’Ana.","aide":"La question s’écrit en deux mots avec accent ; la réponse en un mot sans accent.","type":"trous","segments":["¿",0," no viniste a mi fiesta? — ",1," estaba enferma."],"banque":["Porqué","Por que","Porque","Por qué"]},{"enonce":"Range chaque phrase : le mot qui introduit la suite est-il interrogatif ou relatif ?","aide":"Un relatif reprend un nom ; un interrogatif pose une question, même indirecte.","type":"categories","categories":[{"id":"c0","texte":"Interrogatif (accent écrit)"},{"id":"c1","texte":"Relatif (sans accent)"}],"items":[{"id":"i0","texte":"Pregunta cuánto cuesta"},{"id":"i1","texte":"Mi madre pregunta dónde vives"},{"id":"i2","texte":"La casa donde vivo es vieja"},{"id":"i3","texte":"Dime cuándo llegas"},{"id":"i4","texte":"El libro que leo es nuevo"}]},{"enonce":"Dans la phrase de la mère de Pablo (« …pregunta dónde vives… »), que devient l’écriture de *dónde* ?","aide":"La question est indirecte : elle n’est pas posée directement.","type":"choix","options":[{"id":"a","texte":"Il garde son accent et reçoit ¿ ?"},{"id":"b","texte":"Il perd son accent et les signes ¿ ?"},{"id":"c","texte":"Il garde son accent, mais sans ¿ ni ?"},{"id":"d","texte":"Il perd son accent mais reçoit ¿ ?"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m12"]},"explication":"**el porqué** est un nom masculin (la raison) : un seul mot, avec accent."},{"cle":{"type":"zone","ids":["m4"]},"explication":"**porque** (un mot, sans accent) introduit la réponse, la cause."},{"cle":{"type":"trous","trous":[["por que"],["porque"]]},"affichage":"Por qué · Porque","explication":"**¿Por qué…? — Porque…** : *por qué* pose la question, *porque* donne la réponse."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c1","i3":"c0","i4":"c1"}},"explication":"Les mots **interrogatifs** (même dans une question indirecte) portent l’accent ; les **relatifs** comme *donde* ou *que* n’en portent pas."},{"cle":{"type":"choix","ids":["c"]},"explication":"**dónde** garde son accent : dans une interrogation indirecte, l’accent reste, mais les signes ¿ ? disparaissent."}]$ex$::jsonb),
  ('96f56dbf-91f9-5b3c-b84f-f3c89061370b'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"La journée d’hier à Tolède","competence":"comprendre-langue","situation":"Nico demande à Eva ce qu’elle a fait hier. Eva lui raconte sa journée.","documents":[{"id":"toledo","type":"dialogue","modele":"sms","titre":"Messages de Nico et d’Eva","participants":[{"nom":"Nico","emoji":"👦","cote":"gauche"},{"nom":"Eva","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Nico","texte":"¿Qué hiciste ayer?"},{"qui":"Eva","texte":"Ayer viajé a Toledo. Visité la catedral y comí en un restaurante."},{"qui":"Eva","texte":"Y tú, ¿qué hiciste?"}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les **trois verbes** au passé simple à la 1re personne.","aide":"Ils se terminent par -é ou -í.","type":"zone","document":"toledo","multiple":true},{"enonce":"Associe chaque pronom à la forme de hablar au passé simple.","aide":"Les terminaisons sont -é, -aste, -ó, -amos, -asteis, -aron.","type":"association","gauche":[{"id":"g0","texte":"yo"},{"id":"g1","texte":"tú"},{"id":"g2","texte":"nosotros"},{"id":"g3","texte":"ellos"}],"droite":[{"id":"d0","texte":"hablaron"},{"id":"d1","texte":"hablaste"},{"id":"d2","texte":"hablé"},{"id":"d3","texte":"hablamos"}]},{"enonce":"Complète avec le passé simple de comer.","aide":"Ayer est un marqueur du passé simple.","type":"trous","segments":["Ayer ellos ",0," en un restaurante."],"banque":["comían","comieron","comerán","comen"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m4","m7","m11"]},"explication":"**Viajé, visité, comí** : passé simple à la 1re personne (-é pour les verbes en -ar, -í pour -er/-ir)."},{"cle":{"type":"association","paires":{"g3":"d0","g1":"d1","g0":"d2","g2":"d3"}},"explication":"*Hablé, hablaste, hablamos, hablaron* : le passé simple des verbes en -ar."},{"cle":{"type":"trous","trous":[["comieron"]]},"affichage":"comieron","explication":"**Comieron** : verbe en -er, 3e personne du pluriel, terminaison -ieron."}]$ex$::jsonb),
  ('96f56dbf-91f9-5b3c-b84f-f3c89061370b'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Une nuit d’orage","competence":"manier-langue","situation":"Une élève raconte une nuit d’orage où quelqu’un a sonné à la porte. Elle emploie l’imparfait pour le décor et le passé simple pour l’action.","documents":[{"id":"tormenta","type":"texte","genre":"recit","titre":"Una noche de tormenta","blocs":["Era de noche y llovía. De repente, sonó el timbre. Mi padre abrió la puerta y vio a un hombre mojado.","El hombre dijo: «Me llamo Julián». Mi madre pidió un té y todos durmieron mal esa noche."],"source":"Récit écrit pour l’exercice"}],"questions":[{"enonce":"Touche les **deux verbes** dont la voyelle du radical change à la 3e personne (e devient i, o devient u).","aide":"Ce sont des verbes comme pedir et dormir.","type":"zone","document":"tormenta","multiple":true},{"enonce":"Associe chaque infinitif à sa 1re personne du passé simple.","aide":"Ces verbes forts changent de radical et n’ont pas d’accent.","type":"association","gauche":[{"id":"g0","texte":"tener"},{"id":"g1","texte":"poner"},{"id":"g2","texte":"venir"},{"id":"g3","texte":"decir"}],"droite":[{"id":"d0","texte":"tuve"},{"id":"d1","texte":"vine"},{"id":"d2","texte":"dije"},{"id":"d3","texte":"puse"}]},{"enonce":"Complète avec le passé simple de decir.","aide":"Après un radical en -j, la terminaison perd son i.","type":"trous","segments":["Ellos ",0," la verdad."],"banque":["decieron","dijieron","dijeron","dijeran"]},{"enonce":"Remets en ordre : « J’ai ouvert la porte et j’ai vu une voiture. » La phrase commence par Abrí.","aide":"Deux événements qui se suivent, tous deux au passé simple.","type":"ordre","items":[{"id":"a","texte":"Abrí"},{"id":"b","texte":"y"},{"id":"c","texte":"la puerta"},{"id":"d","texte":"vi"},{"id":"e","texte":"un coche"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m29","m34"]},"explication":"**Pidió** et **durmieron** : à la 3e personne, ces verbes en -ir changent de voyelle (e devient i, o devient u)."},{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g3":"d2","g1":"d3"}},"explication":"*Tuve, puse, vine, dije* : prétérits forts, sans accent écrit."},{"cle":{"type":"trous","trous":[["dijeron"]]},"affichage":"dijeron","explication":"**Dijeron** : après -j, la 3e personne du pluriel est -eron et non -ieron."},{"cle":{"type":"ordre","ids":["a","c","b","d","e"]},"explication":"**Abrí la puerta y vi un coche** : abrí et vi sont deux passés simples, sans accent sur vi."}]$ex$::jsonb),
  ('96f56dbf-91f9-5b3c-b84f-f3c89061370b'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Un week-end à Grenade","competence":"manier-langue","situation":"Une élève raconte un week-end à Grenade. Un tableau rappelle des passés simples forts.","documents":[{"id":"granada","type":"texte","genre":"recit","titre":"Un fin de semana en Granada","blocs":["El sábado fuimos a Granada. Fui guía de mi primo, y él estuvo muy contento.","Mis padres pudieron visitar la Alhambra y mi hermana trajo las entradas. Los guías dijeron que la visita duraba dos horas."],"source":"Récit écrit pour l’exercice"},{"id":"fuertes","type":"tableau","titre":"Pretéritos fuertes","colonnes":["Infinitivo","yo","ellos"],"lignes":[["tener","tuve","tuvieron"],["decir","dije","?"],["traer","traje","?"],["hacer","hice","?"]],"enteteLignes":false,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Touche la forme de **ser** (et non de ir) au passé simple.","aide":"Le sens de la phrase dit si c’est « être » ou « aller ».","type":"zone","document":"granada","multiple":false},{"enonce":"Complète la colonne « ellos » du tableau.","aide":"Après un radical en -j, la 3e personne du pluriel perd son i.","type":"trous","segments":["decir → ",0," ; traer → ",1," ; hacer → ",2],"banque":["dijieron","hacieron","trajieron","hicieron","dijeron","trajeron"]},{"enonce":"Range chaque verbe.","aide":"Les prétérits forts ont un radical particulier : tuv-, pud-, pus-…","type":"categories","categories":[{"id":"c0","texte":"Prétérit fort (radical qui change)"},{"id":"c1","texte":"Régulier"}],"items":[{"id":"i0","texte":"tener"},{"id":"i1","texte":"comer"},{"id":"i2","texte":"poner"},{"id":"i3","texte":"hablar"},{"id":"i4","texte":"poder"}]},{"enonce":"Pourquoi dit-on « dijeron » et non « dijieron » ?","aide":"Regarde la dernière lettre du radical dij-.","type":"choix","options":[{"id":"a","texte":"Parce que dijeron est une forme du présent"},{"id":"b","texte":"Parce que la phrase est au futur de l’indicatif"},{"id":"c","texte":"Parce que decir est un verbe tout à fait régulier"},{"id":"d","texte":"Après un radical en -j, la terminaison perd son i"}],"multiple":false},{"enonce":"Remets en ordre : « Mes parents ont pu visiter l’Alhambra. » La phrase commence par Mis padres.","aide":"Poder au passé simple, suivi de l’infinitif.","type":"ordre","items":[{"id":"a","texte":"Mis padres"},{"id":"b","texte":"visitar"},{"id":"c","texte":"la Alhambra"},{"id":"d","texte":"pudieron"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m5"]},"explication":"**Fui guía** : ici fui vient de ser (je fus). Dans « fuimos a Granada », on est dans le sens aller."},{"cle":{"type":"trous","trous":[["dijeron"],["trajeron"],["hicieron"]]},"affichage":"dijeron · trajeron · hicieron","explication":"**Dijeron, trajeron, hicieron** : dij- et traj- se terminent en -eron ; hacer donne hic-."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c0","i3":"c1","i4":"c0"}},"explication":"*Tener, poder, poner* ont un radical irrégulier ; *hablar* et *comer* sont réguliers."},{"cle":{"type":"choix","ids":["d"]},"explication":"**Dijeron** : après -j, la terminaison -ieron devient -eron."},{"cle":{"type":"ordre","ids":["a","d","b","c"]},"explication":"**Mis padres pudieron visitar la Alhambra** : pudieron est le prétérit fort de poder."}]$ex$::jsonb),
  ('e3daf9fa-22fb-552c-a96d-e56a0c983093'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Une famille de Madrid","competence":"comprendre-langue","situation":"Daniel se présente à son futur correspondant français. Il parle de sa famille et de ce qu’il fait demain.","documents":[{"id":"daniel","type":"texte","genre":"lettre","titre":"Hola desde Madrid","blocs":["Hola, me llamo Daniel y vivo en Madrid. Mis padres trabajan en un banco. Mi hermana come en el colegio, pero yo como en casa. Mañana salgo con mis amigos al cine."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche le verbe conjugué à la **3e personne du pluriel**.","aide":"Le sujet est « mis padres » : ils.","type":"zone","document":"daniel","multiple":false},{"enonce":"Complète avec le verbe comer à la bonne personne.","aide":"Le sujet est « mi hermana » : 3e personne du singulier.","type":"trous","segments":["Mi hermana ",0," en el colegio."],"banque":["come","como","comen","comemos"]},{"enonce":"Associe chaque pronom à la forme de hablar.","aide":"Chaque personne a sa terminaison : -o, -as, -amos, -an.","type":"association","gauche":[{"id":"g0","texte":"yo"},{"id":"g1","texte":"tú"},{"id":"g2","texte":"nosotros"},{"id":"g3","texte":"ellos"}],"droite":[{"id":"d0","texte":"hablo"},{"id":"d1","texte":"hablamos"},{"id":"d2","texte":"hablas"},{"id":"d3","texte":"hablan"}]},{"enonce":"Dans « Mañana salgo con mis amigos », que fait le présent ?","aide":"Le mot « mañana » donne la réponse.","type":"choix","options":[{"id":"a","texte":"Il exprime une obligation"},{"id":"b","texte":"Il exprime une habitude passée"},{"id":"c","texte":"Il exprime un futur proche"},{"id":"d","texte":"Il exprime un souvenir lointain"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m10"]},"explication":"**Trabajan** : la terminaison -an est celle de ellos/ellas pour les verbes en -ar."},{"cle":{"type":"trous","trous":[["come"]]},"affichage":"come","explication":"**Mi hermana come** : -er à la 3e personne du singulier se termine en -e."},{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g1":"d2","g3":"d3"}},"explication":"*Hablo*, *hablas*, *hablamos*, *hablan* : les terminaisons du présent des verbes en -ar."},{"cle":{"type":"choix","ids":["c"]},"explication":"**Mañana salgo** : le présent peut exprimer un futur proche, surtout avec un repère de temps."}]$ex$::jsonb),
  ('e3daf9fa-22fb-552c-a96d-e56a0c983093'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"La semaine chargée de Teresa","competence":"manier-langue","situation":"Teresa écrit à son amie Marta pour lui raconter sa semaine. Elle utilise plusieurs verbes irréguliers.","documents":[{"id":"teresa","type":"texte","genre":"lettre","titre":"Carta de Teresa","blocs":["Querida Marta: esta semana hago muchas cosas. Pongo la mesa, salgo con mis primos y traigo el pan. Mi hermana pide siempre ayuda, y yo no puedo decir que no."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche les **quatre verbes** dont la 1re personne est irrégulière (-go).","aide":"Ils se terminent tous par -go à la forme « yo ».","type":"zone","document":"teresa","multiple":true},{"enonce":"Associe chaque infinitif à sa 1re personne du présent.","aide":"Les verbes en -cer et en -cir suivent conocer.","type":"association","gauche":[{"id":"g0","texte":"conocer"},{"id":"g1","texte":"saber"},{"id":"g2","texte":"ver"},{"id":"g3","texte":"dar"}],"droite":[{"id":"d0","texte":"veo"},{"id":"d1","texte":"sé"},{"id":"d2","texte":"doy"},{"id":"d3","texte":"conozco"}]},{"enonce":"Complète avec le verbe poder à la forme nosotros.","aide":"À nosotros et vosotros, la diphtongue disparaît.","type":"trous","segments":["Nosotros ",0," ir al cine el sábado."],"banque":["puedemos","pueden","podemos","puedes"]},{"enonce":"Dans « mi hermana pide », quel changement de radical observe-t-on par rapport à pedir ?","aide":"Pense à l’infinitif pedir : quelle voyelle change ?","type":"choix","options":[{"id":"a","texte":"u devient ue"},{"id":"b","texte":"e devient ie"},{"id":"c","texte":"o devient ue"},{"id":"d","texte":"e devient i"}],"multiple":false}]}$ex$::jsonb,
