   $ex${"titre":"Un desayuno en el bar","competence":"comprendre-langue","situation":"Mateo raconte son petit-déjeuner dans un bar avec sa famille.","documents":[{"id":"desayuno","type":"texte","genre":"recit","titre":"En el bar","blocs":["Hoy desayunamos en un bar. Yo pido un zumo. Mi hermana pide un café con leche. Nosotros pedimos dos tostadas y los camareros nos sirven enseguida."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche les **trois formes** où le *e* du radical devient *i*.","aide":"Cherche pido, pide et le verbe servir.","type":"zone","document":"desayuno","multiple":true},{"enonce":"Complète avec la bonne forme.","aide":"*Vosotros* est hors de la botte.","type":"trous","segments":["Vosotros ",0," dos tostadas."],"banque":["pidís","piden","pedís","pido"]},{"enonce":"Pourquoi « pedimos » ne change-t-il pas ?","aide":"Compare avec « pido » et « pide ».","type":"choix","options":[{"id":"a","texte":"Pedir est un verbe en -ar qui reste régulier"},{"id":"b","texte":"Le verbe diphtongue à la place de s’affaiblir"},{"id":"c","texte":"L’accent tonique tombe sur la terminaison"},{"id":"d","texte":"Nosotros n’existe pas au présent simple"}],"multiple":false},{"enonce":"Complète avec la bonne forme.","aide":"Le sujet est « mis padres ».","type":"trous","segments":["Mis padres ",0," un helado."],"banque":["pedís","pedí","piden","pedimos"]}]}$ex$::jsonb,
