   $ex${"titre":"La comida del abuelo","competence":"manier-langue","situation":"Lucas raconte un repas de famille. Les verbes en -ir y changent de radical.","documents":[{"id":"comida","type":"texte","genre":"recit","titre":"La comida del domingo","blocs":["Ayer mi abuelo sirvió la comida y nos pidió silencio. Mientras comíamos, siguió contando historias de su infancia.","Mis primos repitieron la sopa y yo tomé agua."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche les **quatre verbes** du passé simple (3e personne) qui s’affaiblissent.","aide":"Ils contiennent un *i* à la place du *e* du radical.","type":"zone","document":"comida","multiple":true},{"enonce":"Complète au passé simple.","aide":"3e personne du pluriel : l’affaiblissement s’applique.","type":"trous","segments":["Ayer mis primos ",0," otro postre."],"banque":["pidió","pedimos","pidieron","pedieron"]},{"enonce":"Associe chaque infinitif à son gérondif.","aide":"Le gérondif de ces verbes s’affaiblit toujours.","type":"association","gauche":[{"id":"g0","texte":"decir"},{"id":"g1","texte":"pedir"},{"id":"g2","texte":"servir"},{"id":"g3","texte":"dormir"}],"droite":[{"id":"d0","texte":"diciendo"},{"id":"d1","texte":"durmiendo"},{"id":"d2","texte":"pidiendo"},{"id":"d3","texte":"sirviendo"}]},{"enonce":"Complète au passé simple.","aide":"À la 1re personne, la terminaison porte l’accent.","type":"trous","segments":["Ayer yo ",0," un helado."],"banque":["pedí","pidió","pedió","pidí"]}]}$ex$::jsonb,
