   $ex${"titre":"Un dimanche à la maison","competence":"comprendre-langue","situation":"Irene et Tomás s’écrivent pour se raconter leur journée et leur semaine.","documents":[{"id":"hoy","type":"dialogue","modele":"sms","titre":"Messages d’Irene et de Tomás","participants":[{"nom":"Irene","emoji":"👧","cote":"gauche"},{"nom":"Tomás","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Irene","texte":"Hola, Tomás. Hoy he comido paella con mi familia."},{"qui":"Tomás","texte":"¡Qué rico! Yo he estudiado toda la mañana."},{"qui":"Irene","texte":"Y esta semana he visto tres películas."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les **trois formes du passé composé**.","aide":"Elles sont formées de haber au présent et d’un participe passé.","type":"zone","document":"hoy","multiple":true},{"enonce":"Pourquoi Irene écrit-elle « hoy he comido » et non « hoy comí » ?","aide":"Regarde le marqueur de temps.","type":"choix","options":[{"id":"a","texte":"Hoy appartient à une période non achevée"},{"id":"b","texte":"La phrase est au futur"},{"id":"c","texte":"Comer est un verbe irrégulier"},{"id":"d","texte":"Hoy est un marqueur du passé simple"}],"multiple":false},{"enonce":"Complète le passé composé de ver.","aide":"Après « he », il faut un participe passé irrégulier.","type":"trous","segments":["Esta semana he ",0," tres películas."],"banque":["viendo","veído","visto","ver"]}]}$ex$::jsonb,
