   $ex${"titre":"Une carte postale de Séville","competence":"manier-langue","situation":"Ana écrit à une amie depuis Séville. Elle parle de sa semaine de voyage, de ce qu’elle a fait hier et de ses voyages passés.","documents":[{"id":"postal","type":"texte","genre":"lettre","titre":"Querida Ana","blocs":["Querida Marta: esta semana hemos visitado Sevilla. Ayer fuimos a la catedral, y hoy hemos comido en un mercado.","El año pasado viajé a Madrid, pero nunca he estado en Cádiz."],"source":"Carte écrite pour l’exercice"}],"questions":[{"enonce":"Range chaque marqueur de temps.","aide":"Si le marqueur contient « este » ou « esta », c’est le passé composé.","type":"categories","categories":[{"id":"c0","texte":"Passé composé"},{"id":"c1","texte":"Passé simple"}],"items":[{"id":"i0","texte":"anoche"},{"id":"i1","texte":"el año pasado"},{"id":"i2","texte":"este mes"},{"id":"i3","texte":"ayer"},{"id":"i4","texte":"hoy"},{"id":"i5","texte":"esta semana"}]},{"enonce":"Touche les **trois formes du passé composé** de la lettre.","aide":"Elles commencent par une forme de haber.","type":"zone","document":"postal","multiple":true},{"enonce":"Remets en ordre : « Je ne l’ai jamais vu. » La phrase commence par No.","aide":"Rien ne s’intercale entre haber et le participe.","type":"ordre","items":[{"id":"a","texte":"lo"},{"id":"b","texte":"he"},{"id":"c","texte":"visto"},{"id":"d","texte":"nunca"},{"id":"e","texte":"No"}]},{"enonce":"Pourquoi écrit-on « ayer fuimos a la catedral » et non « ayer hemos ido » ?","aide":"Le passé simple coupe le fait du présent.","type":"choix","options":[{"id":"a","texte":"Parce que la phrase est une question"},{"id":"b","texte":"Ayer est suivi du participe passé"},{"id":"c","texte":"Ir est un verbe irrégulier"},{"id":"d","texte":"Ayer désigne une période terminée"}],"multiple":false}]}$ex$::jsonb,
