  ('b73881dc-c6e0-5eeb-93a5-9d5399d65b8b'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le journal de Marina","competence":"manier-langue","situation":"Marina a un examen la semaine prochaine. Elle écrit ce qu’elle veut, ce qu’elle craint et ce qu’elle espère.","documents":[{"id":"diario","type":"texte","genre":"lettre","titre":"El diario de Marina","blocs":["Querido diario:","Hoy quiero ir al cine, pero mi madre quiere que estudie más.","Dudo que el examen sea difícil. Creo que sé casi todo.","¡Ojalá apruebe!"],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Pourquoi Marina écrit-elle « quiero ir » sans *que* ?","aide":"Qui veut ? Qui va au cinéma ?","type":"choix","options":[{"id":"a","texte":"Parce que ir est un verbe irrégulier"},{"id":"b","texte":"Parce que la phrase est une question"},{"id":"c","texte":"Le sujet ne change pas : on garde l’infinitif"},{"id":"d","texte":"Le subjonctif est interdit avec quiero"}],"multiple":false},{"enonce":"Touche les **trois verbes au subjonctif** du journal.","aide":"Ils suivent une volonté, un doute et un souhait.","type":"zone","document":"diario","multiple":true},{"enonce":"Range chaque début de phrase selon le mode qui suit.","aide":"Déclaration, perception, certitude : indicatif. Volonté, doute, jugement, certitude niée : subjonctif.","type":"categories","categories":[{"id":"c0","texte":"Indicatif"},{"id":"c1","texte":"Subjonctif"}],"items":[{"id":"i0","texte":"Veo que…"},{"id":"i1","texte":"No creo que…"},{"id":"i2","texte":"Dudo que…"},{"id":"i3","texte":"Es necesario que…"},{"id":"i4","texte":"Es verdad que…"},{"id":"i5","texte":"Creo que…"}]},{"enonce":"Remets en ordre : « Ma mère veut que j’étudie beaucoup. » La phrase commence par Mi.","aide":"Le verbe de volonté est suivi de que + subjonctif.","type":"ordre","items":[{"id":"a","texte":"Mi madre"},{"id":"b","texte":"estudie"},{"id":"c","texte":"quiere que"},{"id":"d","texte":"mucho"}]}]}$ex$::jsonb,
