   $ex${"titre":"Passe-moi ton stylo","competence":"manier-langue","situation":"Marta a oublié son stylo. Elle le demande à Leo, avec des pronoms placés comme il faut.","documents":[{"id":"boli","type":"dialogue","modele":"sms","titre":"Messages de Marta et Leo","participants":[{"nom":"Marta","emoji":"👧","cote":"gauche"},{"nom":"Leo","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Marta","texte":"Necesito tu bolígrafo. ¡Dámelo, por favor!"},{"qui":"Leo","texte":"Aquí tienes. ¿Quieres también el cuaderno?"},{"qui":"Marta","texte":"No, no me lo des. Ya lo tengo."},{"qui":"Leo","texte":"Vale. Voy a decírtelo: mañana hay examen."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le verbe à l’**impératif affirmatif** dont les pronoms sont soudés.","aide":"C’est dans la première demande de Marta.","type":"zone","document":"boli","multiple":false},{"enonce":"Pourquoi « dámelo » porte-t-il un accent écrit ?","aide":"Pense à la forme de départ : da.","type":"choix","options":[{"id":"a","texte":"Parce que la phrase est une question"},{"id":"b","texte":"Pour garder la syllabe tonique de *da*"},{"id":"c","texte":"Parce qu’il y a deux pronoms soudés"},{"id":"d","texte":"Parce que *lo* est une syllabe accentuée"}],"multiple":false},{"enonce":"Remets en ordre : « Ne me le donne pas. » La phrase commence par No.","aide":"À l’impératif négatif, les pronoms restent devant le verbe.","type":"ordre","items":[{"id":"a","texte":"No"},{"id":"b","texte":"lo"},{"id":"c","texte":"me"},{"id":"d","texte":"des"}]},{"enonce":"Quelle phrase est équivalente à « Te lo voy a decir » ?","aide":"Avec un verbe conjugué + infinitif, les deux places sont admises.","type":"choix","options":[{"id":"a","texte":"Te voy a lo decir"},{"id":"b","texte":"Voy decirtelo a"},{"id":"c","texte":"Voy a decírtelo"},{"id":"d","texte":"Voy a te lo decir"}],"multiple":false}]}$ex$::jsonb,
