   $ex${"titre":"Pero ou sino ?","competence":"manier-langue","situation":"Carmen se présente à sa correspondante, puis le lycée annonce un concert. Il faut choisir entre « pero » et « sino ».","documents":[{"id":"carta","type":"texte","genre":"lettre","titre":"Carmen se presenta","blocs":["Hola, soy Carmen. No soy de Madrid, sino de Sevilla.","Mi hermano Raúl no estudia en mi colegio, sino en otro.","Raúl es muy tímido, pero canta muy bien.","En clase no habla, sino que susurra."],"source":"Texte écrit pour l’exercice"},{"id":"afiche","type":"fiche","modele":"affiche","entete":"Concierto del instituto","sousTitre":"Sábado, 18 h","emoji":"🎻","lignes":[{"texte":"No es un concierto de rock,"},{"texte":"sino un concierto de música clásica."}],"pied":"Entrada gratuita","teinte":"violet","titre":"Affiche du lycée","source":"Affiche écrite pour l’exercice"}],"questions":[{"enonce":"Touche les **trois mots** qui **rectifient** ce qui vient d’être nié.","aide":"Ils suivent une négation et introduisent la bonne information.","type":"zone","document":"carta","multiple":true},{"enonce":"Pourquoi Carmen écrit-elle « Raúl es muy tímido, pero canta muy bien » ?","aide":"Y a-t-il une négation à rectifier dans cette phrase ?","type":"choix","options":[{"id":"a","texte":"Pero oppose deux idées sans rectifier de négation"},{"id":"b","texte":"Raúl est présenté comme un garçon qui n’est pas timide"},{"id":"c","texte":"Sino ne s’emploie jamais après un adjectif"},{"id":"d","texte":"Pero ne s’emploie qu’avec le verbe cantar"}],"multiple":false},{"enonce":"Complète avec **pero**, **sino** ou **sino que**.","aide":"Rectifier : sino. Opposer : pero. Devant un verbe conjugué : sino que.","type":"trous","segments":["Carmen no es alta, ",0," baja. Es baja, ",1," muy rápida. No cierra la puerta, ",2," la abre."],"banque":["ni","sino","sino que","pero"]},{"enonce":"Remets en ordre le début de l’affiche : « Ce n’est pas un cours, mais un concert. » La phrase commence par No.","aide":"Sino rectifie ce qui vient d’être nié.","type":"ordre","items":[{"id":"a","texte":"No"},{"id":"b","texte":"es"},{"id":"c","texte":"un curso"},{"id":"d","texte":"un concierto"},{"id":"e","texte":"sino"}]},{"enonce":"Range chaque phrase selon le mot qui manque.","aide":"Peut-on corriger ce qui vient d’être nié par un terme opposé ?","type":"categories","categories":[{"id":"c0","texte":"pero (oppose)"},{"id":"c1","texte":"sino (rectifie)"}],"items":[{"id":"i0","texte":"No bebo café, ___ té"},{"id":"i1","texte":"Es pequeño, ___ muy fuerte"},{"id":"i2","texte":"No es caro, ___ barato"},{"id":"i3","texte":"Estoy cansado, ___ voy al cine"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m7","m18","m33"]},"explication":"**sino** (trois fois) : après une négation, il rectifie. « No soy de Madrid, sino de Sevilla. »"},{"cle":{"type":"choix","ids":["a"]},"explication":"**Pero** oppose deux idées (timide / chante bien) ; il n’y a aucune négation à corriger, donc pas de *sino*."},{"cle":{"type":"trous","trous":[["sino"],["pero"],["sino que"]]},"affichage":"sino · pero · sino que","explication":"**sino** (alta ≠ baja), **pero** (opposition simple), **sino que** (devant le verbe conjugué *abre*)."},{"cle":{"type":"ordre","ids":["a","b","c","e","d"]},"explication":"**No es un curso sino un concierto** : la négation, puis *sino* pour rectifier."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c1","i3":"c0"}},"explication":"**sino** rectifie après une négation (caro → barato, café → té) ; **pero** oppose sans rectifier."}]$ex$::jsonb),
