 deux cousins, puis d’autres personnes.","type":"choix","options":[{"id":"a","texte":"Aucun des cousins"},{"id":"b","texte":"Tous les cousins sans exception"},{"id":"c","texte":"Les autres, le reste des personnes"},{"id":"d","texte":"Les deux cousins seulement"}],"multiple":false},{"enonce":"Remets en ordre : « Chacun a ses projets. » La phrase commence par Cada.","aide":"*Cada uno* = chacun.","type":"ordre","items":[{"id":"a","texte":"sus"},{"id":"b","texte":"tiene"},{"id":"c","texte":"planes"},{"id":"d","texte":"uno"},{"id":"e","texte":"Cada"}]}]}$ex$::jsonb,
