   $ex${"titre":"Le tableau d’annonces","competence":"manier-langue","situation":"Dans le hall d’un centre culturel, plusieurs annonces utilisent le pronom *se*.","documents":[{"id":"tablon","type":"fiche","modele":"panneau","entete":"Tablón de anuncios","sousTitre":"Centro cultural · entrada","emoji":"📌","lignes":[{"texte":"Se venden bicis de segunda mano","id":"z1"},{"texte":"Aquí se come muy bien","id":"z2"},{"texte":"Se buscan voluntarios para la feria","id":"z3"},{"texte":"Se alquila un piso pequeño","id":"z4"}],"teinte":"jaune","source":"Annonces écrites pour l’exercice"}],"questions":[{"enonce":"Touche les **deux annonces** où le verbe est au **pluriel** parce qu’il s’accorde avec son sujet.","aide":"Cherche venden et buscan.","type":"zone","document":"tablon","multiple":true},{"enonce":"Complète avec la bonne forme.","aide":"Le sujet est « pisos » (pluriel).","type":"trous","segments":["Se ",0," pisos baratos en el barrio."],"banque":["vender","vende","venden","vendo"]},{"enonce":"Dans « Aquí se come muy bien », quelle est la valeur de *se* ?","aide":"Personne n’est désigné : on parle de tout le monde.","type":"choix","options":[{"id":"a","texte":"Réfléchie : quelqu’un se mange lui-même"},{"id":"b","texte":"Lexicale : comerse est toujours pronominal"},{"id":"c","texte":"Réciproque : deux personnes se mangent"},{"id":"d","texte":"Impersonnelle : « on mange bien ici »"}],"multiple":false},{"enonce":"Associe chaque phrase espagnole à son sens.","aide":"Quatre valeurs : passive, impersonnelle, réciproque, réfléchie.","type":"association","gauche":[{"id":"g0","texte":"Se venden pisos"},{"id":"g1","texte":"Se dice que…"},{"id":"g2","texte":"Se escriben"},{"id":"g3","texte":"Se lava"}],"droite":[{"id":"d0","texte":"On dit que…"},{"id":"d1","texte":"Des appartements sont à vendre"},{"id":"d2","texte":"Il se lave lui-même"},{"id":"d3","texte":"Ils s’écrivent l’un à l’autre"}]}]}$ex$::jsonb,
