   $ex${"titre":"Me voy al cine","competence":"manier-langue","situation":"Álvaro propose un plan à Clara. Ses réponses contiennent plusieurs verbes pronominaux.","documents":[{"id":"cine","type":"dialogue","modele":"sms","titre":"Mensajes de Álvaro y Clara","participants":[{"nom":"Álvaro","emoji":"👦","cote":"gauche"},{"nom":"Clara","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Álvaro","texte":"¿Te quedas en casa esta tarde?"},{"qui":"Clara","texte":"No, me voy al cine. Me pongo contenta cuando veo una película."},{"qui":"Clara","texte":"¿Te acuerdas de la del otro día? Luego nos escribimos."}],"source":"Messages écrits pour l’exercice"},{"id":"sentidos","type":"tableau","titre":"Con o sin pronombre","colonnes":["Sin pronombre","Con pronombre"],"lignes":[["ir (aller)","irse (?)"],["dormir (dormir)","dormirse (?)"],["acordar (décider)","acordarse de (?)"]],"enteteLignes":false,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Touche le verbe qui signifie **« s’en aller, partir »**.","aide":"*Irse* ne veut pas dire « aller ».","type":"zone","document":"cine","multiple":false},{"enonce":"Dans « Me pongo contenta », que signifie *ponerse* ?","aide":"Contenta décrit un état : le pronom exprime un changement.","type":"choix","options":[{"id":"a","texte":"Devenir, se mettre dans un état"},{"id":"b","texte":"Mettre un objet quelque part"},{"id":"c","texte":"Se souvenir"},{"id":"d","texte":"S’en aller"}],"multiple":false},{"enonce":"Complète avec la traduction qui convient.","aide":"Le pronom change le sens du verbe : compare avec la colonne de gauche.","type":"trous","segments":["irse → ",0," ; dormirse → ",1," ; acordarse de → ",2],"banque":["se souvenir","rester","s’endormir","partir","devenir"]},{"enonce":"Range chaque phrase : passive ou impersonnelle ?","aide":"Cherche si un nom pluriel est le sujet du verbe.","type":"categories","categories":[{"id":"c0","texte":"Passive (le verbe s’accorde)"},{"id":"c1","texte":"Impersonnelle (verbe au singulier)"}],"items":[{"id":"i0","texte":"Se alquilan coches"},{"id":"i1","texte":"Se venden pisos"},{"id":"i2","texte":"Se habla de política"},{"id":"i3","texte":"Aquí se come bien"}]}]}$ex$::jsonb,
