   $ex${"titre":"Une maison vide","competence":"manier-langue","situation":"Lucía rentre chez elle et ne trouve personne. Elle observe quelques indices et fait des suppositions.","documents":[{"id":"casa","type":"texte","genre":"recit","titre":"Una casa vacía","blocs":["Cuando llegué a casa, no había nadie. La puerta estaba abierta. Serían las ocho. Mi hermano habría salido con prisa: había un zapato en el suelo.","Mi madre estará en el supermercado, pero no estoy segura. Quizás venga pronto."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche les **deux formes** du conditionnel qui supposent sur le **passé**.","aide":"Le conditionnel (et le conditionnel passé) suppose sur le passé, comme le futur suppose sur le présent.","type":"zone","document":"casa","multiple":true},{"enonce":"Que veut dire « Mi madre estará en el supermercado » ?","aide":"Lucía ne sait pas : elle suppose, en ce moment.","type":"choix","options":[{"id":"a","texte":"Ma mère veut aller au supermarché"},{"id":"b","texte":"Ma mère sera au supermarché demain"},{"id":"c","texte":"Ma mère doit être au supermarché"},{"id":"d","texte":"Ma mère était au supermarché"}],"multiple":false},{"enonce":"Pourquoi Lucía écrit-elle « quizás venga » plutôt que « quizás viene » ?","aide":"Après quizás, le subjonctif dit « je n’en sais rien ».","type":"choix","options":[{"id":"a","texte":"Parce que le verbe est au passé"},{"id":"b","texte":"Pour montrer une probabilité plus faible"},{"id":"c","texte":"Pour montrer une probabilité plus forte"},{"id":"d","texte":"Parce que la phrase est négative"}],"multiple":false},{"enonce":"Remets en ordre : « Il se peut qu’il pleuve demain. » La phrase commence par Puede.","aide":"Puede que est suivi du subjonctif.","type":"ordre","items":[{"id":"a","texte":"que"},{"id":"b","texte":"mañana"},{"id":"c","texte":"Puede"},{"id":"d","texte":"llueva"}]}]}$ex$::jsonb,
