   $ex${"titre":"La lettre de la grand-mère","competence":"analyser-texte","situation":"Une grand-mère espagnole écrit à son petit-fils pour lui raconter son enfance. Elle emploie plusieurs démonstratifs.","documents":[{"id":"abuela","type":"texte","genre":"lettre","titre":"Carta de la abuela","blocs":["Querido nieto:","Este año cumplo setenta años. En aquel entonces, cuando tenía tu edad, vivíamos en una aldea pequeña.","Aquellos tiempos eran duros: no había coche ni televisión, y eso nos parecía normal.","Todo aquello me parece hoy un sueño. Esto que te escribo es un recuerdo."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche les **trois démonstratifs neutres** de la lettre.","aide":"Ils ne sont jamais suivis d’un nom.","type":"zone","document":"abuela","multiple":true},{"enonce":"Pourquoi la grand-mère écrit-elle « aquellos tiempos » et non « estos tiempos » ?","aide":"Les démonstratifs marquent aussi la distance dans le temps.","type":"choix","options":[{"id":"a","texte":"Tiempos est un nom féminin"},{"id":"b","texte":"Elle évoque une époque lointaine"},{"id":"c","texte":"Aquellos est toujours un pronom"},{"id":"d","texte":"Elle parle du moment présent"}],"multiple":false},{"enonce":"Complète en reprenant l’idée de toute la phrase.","aide":"Une phrase entière se reprend par un neutre.","type":"trous","segments":["No vino a la fiesta, y ",0," me molestó."],"banque":["aquel","esta","ese","eso"]},{"enonce":"Associe chaque tournure à son sens.","aide":"Cherche les mots entonces, año et tiempos.","type":"association","gauche":[{"id":"g0","texte":"este año"},{"id":"g1","texte":"aquellos tiempos"},{"id":"g2","texte":"en aquel entonces"},{"id":"g3","texte":"ni esto ni aquello"}],"droite":[{"id":"d0","texte":"cette année"},{"id":"d1","texte":"à cette époque-là"},{"id":"d2","texte":"ni l’un ni l’autre"},{"id":"d3","texte":"ces temps lointains"}]},{"enonce":"Range chaque phrase selon que le démonstratif est adjectif ou pronom.","aide":"Y a-t-il un nom juste après le démonstratif ?","type":"categories","categories":[{"id":"c0","texte":"Adjectif (suivi d’un nom)"},{"id":"c1","texte":"Pronom (employé seul)"}],"items":[{"id":"i0","texte":"Esa es grande"},{"id":"i1","texte":"Esa casa es grande"},{"id":"i2","texte":"Este libro es mío"},{"id":"i3","texte":"Este es mío"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m29","m34","m40"]},"explication":"**eso, aquello, esto** : les neutres sont invariables, sans accent, et ne précèdent jamais un nom."},{"cle":{"type":"choix","ids":["b"]},"explication":"**aquellos tiempos** évoque une époque lointaine ; *este año* désigne l’année en cours."},{"cle":{"type":"trous","trous":[["eso"]]},"affichage":"eso","explication":"**eso** reprend toute l’idée de la phrase ; on ne reprend jamais une phrase par *ese*."},{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g3":"d2","g1":"d3"}},"explication":"Ces quatre tournures se retrouvent dans la lettre ou dans le cours."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c0","i3":"c1"}},"explication":"Adjectif et pronom ont la **même forme** ; depuis la réforme de 2010, le pronom ne prend plus d’accent."}]$ex$::jsonb),
  ('2cf389b6-dd29-59bf-8cb7-7e2cc85d733b'::uuid, 1, 1, 5, 20, 3,
