   $ex${"titre":"La lettre d’Inés à sa correspondante","competence":"manier-langue","situation":"Inés écrit à Clara pour lui parler de sa famille. Attention : avec ser ou avec estar, un même adjectif change de sens.","documents":[{"id":"carta","type":"texte","genre":"lettre","titre":"Carta de Inés","blocs":["Querida Clara:","Mi hermano Álvaro es muy listo, pero hoy está malo: tiene fiebre y no está listo para ir al colegio.","En casa, la sopa de mi abuela está rica y el agua está fría.","Mi tío, en cambio, es rico: tiene tres coches y una casa enorme."],"source":"Lettre écrite pour l’exercice"}],"questions":[{"enonce":"Touche l’adjectif qui veut dire « **malade** » (Álvaro a de la fièvre).","aide":"Il suit « está » et rime avec le contraire de « bueno ».","type":"zone","document":"carta","multiple":false},{"enonce":"Touche l’adjectif qui veut dire « **riche** » (de l’argent), et pas « délicieux ».","aide":"Deux mots se ressemblent dans la lettre : l’un parle de la soupe, l’autre de l’oncle.","type":"zone","document":"carta","multiple":false},{"enonce":"Que veut dire « no está listo para ir al colegio » ?","aide":"Compare « es muy listo » au début de la lettre et « no está listo ».","type":"choix","options":[{"id":"a","texte":"Il n’est pas content d’aller au collège"},{"id":"b","texte":"Il n’est pas autorisé à aller au collège"},{"id":"c","texte":"Il n’est pas prêt à aller au collège"},{"id":"d","texte":"Il n’est pas assez malin pour aller au collège"}],"multiple":false},{"enonce":"Complète pour dire qu’Álvaro s’ennuie en classe.","aide":"S’ennuyer est un état passager.","type":"trous","segments":["Mi hermano ",0," aburrido en clase."],"banque":["está","estoy","es","son"]},{"enonce":"Associe chaque expression à son sens.","aide":"Ser dit ce que la personne est ; estar dit comment elle va.","type":"association","gauche":[{"id":"g0","texte":"ser listo"},{"id":"g1","texte":"estar listo"},{"id":"g2","texte":"ser malo"},{"id":"g3","texte":"estar malo"}],"droite":[{"id":"d0","texte":"être malin"},{"id":"d1","texte":"être malade"},{"id":"d2","texte":"être prêt"},{"id":"d3","texte":"être méchant"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m11"]},"explication":"**está malo** : *estar malo* = être malade ; *ser malo* = être méchant."},{"cle":{"type":"zone","ids":["m41"]},"explication":"**es rico** : *ser rico* = être riche ; *estar rico* = être délicieux (la soupe *está rica*)."},{"cle":{"type":"choix","ids":["c"]},"explication":"**estar listo** = être prêt ; **ser listo** = être malin. Le verbe change le sens de l’adjectif."},{"cle":{"type":"trous","trous":[["esta"]]},"affichage":"está","explication":"**está aburrido** : *estar aburrido* = s’ennuyer ; *ser aburrido* = être ennuyeux."},{"cle":{"type":"association","paires":{"g0":"d0","g3":"d1","g1":"d2","g2":"d3"}},"explication":"Avec *ser*, c’est la nature (malin, méchant) ; avec *estar*, c’est un état (prêt, malade)."}]$ex$::jsonb),
