ultiple":false},{"enonce":"Pourquoi Mario écrit-il « Hoy estoy cansado » et non « Hoy soy cansado » ?","aide":"Se demander si l’on décrit ce qu’est le sujet ou comment il va.","type":"choix","options":[{"id":"a","texte":"Être fatigué est une origine : on emploie estar"},{"id":"b","texte":"Estar remplace ser avec tous les adjectifs en -ado"},{"id":"c","texte":"Soy ne peut pas s’employer avec le mot hoy"},{"id":"d","texte":"Être fatigué est un état passager : on emploie estar"}],"multiple":false}]}$ex$::jsonb,
