   $ex${"titre":"Retard à la gare","competence":"manier-langue","situation":"Un élève arrive trop tard à la gare. Il raconte l’histoire, puis son père lui parle au téléphone.","documents":[{"id":"estacion","type":"texte","genre":"recit","titre":"En la estación","blocs":["Cuando llegué a la estación, el tren ya había salido. Hubo un retraso de una hora, y mucha gente esperaba en el andén.","Por teléfono, mi padre dice : « Mañana, a las ocho, ya habré llegado a casa. »"],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche l’**auxiliaire** du plus-que-parfait (il a déjà quitté la gare).","aide":"C’est le mot qui précède le participe *salido*.","type":"zone","document":"estacion","multiple":false},{"enonce":"Touche l’auxiliaire du **futur antérieur**.","aide":"Le père parle de demain à huit heures.","type":"zone","document":"estacion","multiple":false},{"enonce":"Dans « Hubo un retraso », à quel temps est *hubo* ?","aide":"Le retard est un événement ponctuel, terminé.","type":"choix","options":[{"id":"a","texte":"Au futur de hay"},{"id":"b","texte":"À l’imparfait de hay"},{"id":"c","texte":"Au passé simple de hay"},{"id":"d","texte":"Au présent de haber auxiliaire"}],"multiple":false},{"enonce":"Complète avec le futur antérieur.","aide":"« Pour lundi » parle du futur ; le sujet est pluriel.","type":"trous","segments":["Para el lunes, mis primos ya ",0," vuelto."],"banque":["habían","han","habrán","hayan"]},{"enonce":"Remets en ordre : « Je ne l’ai jamais vu. » La phrase commence par No.","aide":"Rien ne se glisse entre *he* et *visto*.","type":"ordre","items":[{"id":"a","texte":"he"},{"id":"b","texte":"No"},{"id":"c","texte":"nunca"},{"id":"d","texte":"visto"},{"id":"e","texte":"lo"}]}]}$ex$::jsonb,
