ciendo"}]},{"enonce":"Touche le verbe qui exprime une **évolution venue du passé**.","aide":"Il est suivi de diciendo.","type":"zone","document":"carta","multiple":false},{"enonce":"Que signifie « acabé aprobando » ?","aide":"*Acabar* + gérondif exprime l’aboutissement.","type":"choix","options":[{"id":"a","texte":"Je vais réussir"},{"id":"b","texte":"J’ai fini de réussir"},{"id":"c","texte":"Je suis en train de réussir"},{"id":"d","texte":"J’ai fini par réussir"}],"multiple":false}]}$ex$::jsonb,
