   $ex${"titre":"Le règlement du camp d’été","competence":"comprendre-langue","situation":"Marta est monitrice dans un camp d’été à Ávila. Elle écrit à Pablo, un nouvel arrivé, pour lui dire ce qu’il faut faire demain.","documents":[{"id":"camp","type":"dialogue","modele":"sms","titre":"Messages de Marta et de Pablo","participants":[{"nom":"Marta","emoji":"👩","cote":"gauche"},{"nom":"Pablo","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Marta","texte":"Hola, Pablo. Mañana hay que levantarse a las siete."},{"qui":"Pablo","texte":"Vale. Yo tengo que llamar a mi madre antes del desayuno."},{"qui":"Marta","texte":"Perfecto. Y hay que llevar gorra: hace mucho sol."},{"qui":"Pablo","texte":"Entonces tengo que buscar mi gorra esta noche."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les **deux expressions** qui disent une règle valable pour tout le monde.","aide":"Cherche l’expression qui n’a pas de sujet : elle ne parle de personne en particulier.","type":"zone","document":"camp","multiple":true},{"enonce":"Que dit Pablo avec « tengo que llamar a mi madre » ?","aide":"Regarde le sujet de la phrase : « yo ».","type":"choix","options":[{"id":"a","texte":"Que tout le monde doit appeler sa mère"},{"id":"b","texte":"Que lui seul doit appeler sa mère"},{"id":"c","texte":"Qu’il a déjà appelé sa mère"},{"id":"d","texte":"Qu’il a le droit d’appeler sa mère"}],"multiple":false},{"enonce":"Complète la règle impersonnelle, sans sujet.","aide":"Une règle pour tous ne désigne personne : quelle tournure n’a pas de sujet ?","type":"trous","segments":["Regla del campamento: ",0," respetar el silencio por la noche."],"banque":["tengo que","tenemos que","hay que","tienes que"]}]}$ex$::jsonb,
